430	+// A DIP value: the token file promises whole numbers, so anything else is a
431	+// malformed file rather than something to round.
432	+int parse_dip(const nlohmann::json& group, const std::string& path, const char* name)
433	+{
434	+    const nlohmann::json& value = group.at(name);
435	+    if (!value.is_number_integer())
436	+        throw std::runtime_error("design token " + path + "." + name + " is not a whole number of DIP");
437	+    return value.get<int>();
438	+}
