440	+TextRole parse_text_role(const nlohmann::json& recipe, const std::string& path)
441	+{
442	+    const std::string name = recipe.at("textRole").get<std::string>();
443	+    if (name == "pageTitle") return TextRole::PageTitle;
444	+    if (name == "section")   return TextRole::Section;
445	+    if (name == "body")      return TextRole::Body;
446	+    if (name == "label")     return TextRole::Label;
447	+    if (name == "metadata")  return TextRole::Metadata;
448	+    throw std::runtime_error("design token " + path + ".textRole names an unknown role: " + name);
449	+}
